1	/**
2	 * Which checkouts the host may run Git in. The agent's sandbox can write its worktree (its `.git` pointer and nested
3	 * repositories included) but nothing outside it, and Git reads the configuration of whatever repository `.git` leads
4	 * to, so a planted one is a way to run a command on the host. Pure file-system checks, shared by the worktree Git helper
5	 * (`worktrunk/git.ts`), the session's own Git helpers and the checkpoint manager; no dependency on any of them.
6	 */
7	import * as fs from "node:fs";
8	import * as path from "node:path";
9	
10	function inside(root: string, candidate: string): boolean {
11	  return candidate === root || candidate.startsWith(root + path.sep);
12	}
13	
14	/** Variables that change how Git reads pathspecs; an inherited one would turn a `:(top)` magic pathspec literal or case-insensitive. */
15	export const PATHSPEC_MODE_ENV: readonly string[] = ["GIT_LITERAL_PATHSPECS", "GIT_GLOB_PATHSPECS", "GIT_NOGLOB_PATHSPECS", "GIT_ICASE_PATHSPECS"];
16	
17	/**
18	 * The path in a `.git` pointer file, read the way Git reads it: the content must start with `gitdir: `, only the
19	 * trailing line break is dropped, and nothing else is trimmed. A guard that trimmed would resolve a different directory
20	 * than Git does for `gitdir: x ` and could be shown a harmless one; such a pointer is refused instead.
21	 */
22	export function parseGitfilePointer(content: string): string | undefined {
23	  if (!content.startsWith("gitdir: ")) return undefined;
24	  const target = content.slice("gitdir: ".length).replace(/\r?\n$/, "");
25	  if (target === "" || target !== target.trim() || /[\0\r\n]/.test(target)) return undefined;
26	  return target;
27	}
28	
29	/** Whether `root` (which has a `.git` DIRECTORY) is a linked worktree of an enclosing repository, registered there with a `.git` FILE it no longer has. */
30	function replacedWorktreeReason(root: string): string | undefined {
31	  for (let dir = path.dirname(root); ; dir = path.dirname(dir)) {
32	    const registry = path.join(dir, ".git", "worktrees");
33	    try {
34	      for (const name of fs.readdirSync(registry)) {
35	        const recorded = fs.readFileSync(path.join(registry, name, "gitdir"), "utf8").trim();
36	        if (path.basename(recorded) === ".git" && fs.realpathSync(path.dirname(path.resolve(registry, name, recorded))) === root) {
37	          return `${root} is a linked worktree registered in ${dir} whose .git file was replaced by a repository`;
38	        }
39	      }
40	    } catch { /* no registry here */ }
41	    if (path.dirname(dir) === dir) return undefined;
42	  }
43	}
44	
45	/**
46	 * The agent runs in a sandbox that can write its worktree, `.git` pointer file and any nested repository included, but
47	 * nothing outside it. Git reads the configuration of whatever repository `.git` leads to; a planted one can carry
48	 * commands (`filter.*.clean`, `commit.gpgsign` with `gpg.program`) that would run on the host. A checkout is trusted only
49	 * when every `.git` file on the way up is a plain pointer to a Git directory OUTSIDE the outermost linked worktree
50	 * (outside what the agent can write) that points back at it (`gitdir` of a `<common>/worktrees/<name>` entry, or
51	 * `core.worktree` of a separate or submodule Git directory), and no repository with a real `.git` directory sits inside
52	 * a linked worktree. `gitDir`/`workTree` are the verified pair for the nearest `.git` file: Git is then run against them
53	 * directly, so a pointer rewritten after this check is not re-read.
54	 */
55	export function verifyCheckout(cwd: string): { reason?: string; gitDir?: string; workTree?: string } {
56	  let start: string;
57	  try { start = fs.realpathSync(cwd); } catch { return {}; }
58	  const files: string[] = [];
59	  const directories: string[] = [];
60	  for (let dir = start; ; dir = path.dirname(dir)) {
61	    try {
62	      if (fs.lstatSync(path.join(dir, ".git")).isDirectory()) directories.push(dir); else files.push(dir);
63	    } catch { /* no .git here */ }
64	    if (path.dirname(dir) === dir) break;
65	  }
66	  // The agent-writable boundary is the outermost LINKED worktree (its `.git` leads to `<common>/worktrees/<name>`). A
67	  // `.git` file above it (a bare-repository layout `project/.git` -> `.bare`) is the operator's, not the agent's.
68	  const isLinkedRoot = (root: string): boolean => {
69	    try {
70	      const target = parseGitfilePointer(fs.readFileSync(path.join(root, ".git"), "utf8"));
71	      return target !== undefined && path.basename(path.dirname(fs.realpathSync(path.resolve(root, target)))) === "worktrees";
72	    } catch { return false; }
73	  };
74	  const outer = [...files].reverse().find(isLinkedRoot) ?? files[files.length - 1];
75	  if (!outer) {
76	    // A plain repository (or none). But a registered linked worktree whose `.git` file the agent replaced by a repository
77	    // looks exactly like one: the main repository's worktree registry says it is not.
78	    const root = directories[0];
79	    const replaced = root === undefined ? undefined : replacedWorktreeReason(root);
80	    return replaced ? { reason: replaced } : {};
81	  }
82	  files.splice(0, files.length, ...files.filter((root) => inside(outer, root)));
83	  const planted = directories.find((dir) => inside(outer, dir));
84	  if (planted) return { reason: `${planted} is a repository nested inside the linked worktree ${outer}` };
85	  let pinned: { gitDir: string; workTree: string } | undefined;
86	  for (const root of files) {
87	    const dotGit = path.join(root, ".git");
88	    try {
89	      const stat = fs.lstatSync(dotGit);
90	      if (stat.isSymbolicLink() || !stat.isFile() || stat.size > 4096) return { reason: `${dotGit} is not a plain pointer file` };
91	      const target = parseGitfilePointer(fs.readFileSync(dotGit, "utf8"));
92	      if (target === undefined) return { reason: `${dotGit} is not a well-formed gitdir pointer` };
93	      const admin = fs.realpathSync(path.resolve(root, target));
94	      if (inside(outer, admin)) return { reason: `${dotGit} leads into a repository inside the worktree itself` };
95	      let pointsBack = false;
96	      if (path.basename(path.dirname(admin)) === "worktrees") {
97	        const common = fs.realpathSync(path.dirname(path.dirname(admin)));
98	        if (inside(outer, common)) return { reason: `${dotGit} leads into a repository inside the worktree itself` };
99	        pointsBack = fs.realpathSync(path.resolve(admin, fs.readFileSync(path.join(admin, "gitdir"), "utf8").trim())) === path.join(root, ".git");
100	      } else {
101	        const configured = /^\s*worktree\s*=\s*(.+?)\s*$/m.exec(fs.readFileSync(path.join(admin, "config"), "utf8"));
102	        pointsBack = configured !== null && fs.realpathSync(path.resolve(admin, configured[1])) === root;
103	      }
104	      if (!pointsBack) return { reason: `the Git directory behind ${dotGit} does not point back at it` };
105	      pinned ??= { gitDir: admin, workTree: root };
106	    } catch {
107	      return { reason: `${dotGit} could not be verified` };
108	    }
109	  }
110	  return pinned ?? {};
111	}
112	
113	/** `git submodule status` lines as {path, initialised}; a path may contain spaces. */
114	export function parseSubmoduleStatus(listing: string): Array<{ path: string; initialised: boolean }> {
115	  const found: Array<{ path: string; initialised: boolean }> = [];
116	  for (const line of listing.split("\n")) {
117	    const match = /^(.)[0-9a-f]{40,64} (.*?)(?: \(.*\))?$/.exec(line);
118	    if (match) found.push({ path: match[2], initialised: match[1] !== "-" });
119	  }
120	  return found;
121	}
122	
123	/** The reason `cwd` is not a trusted checkout (see `verifyCheckout`), or undefined. */
