104	  if (staged.length > 0) {
105	    git(dir, [...config, "add", "-f", "--pathspec-from-file=-", "--pathspec-file-nul"], { env: { ...env, GIT_LITERAL_PATHSPECS: "1" }, input: staged.join("\0") + "\0" });
106	  }
107	}
