109	/** HEAD, and the tree of the working state: HEAD^{tree} when clean, else a snapshot via a temporary index. */
110	export function workingState(dir: string, dirty: boolean): WorkingState {
111	  const head = gitOut(dir, ["rev-parse", "--verify", "HEAD"]);
112	  if (!dirty) return { head, tree: gitOut(dir, ["rev-parse", "--verify", "HEAD^{tree}"]), dirty };
113	  return { head, tree: snapshotTree(dir, false), dirty };
114	}
